def validate_items(items):
    for item in items:
        if item['price'] < 0 or item['quantity'] < 0:
            raise ValueError("Item price and quantity must be non-negative.")

def calculate_pricing(items, is_vip):
    subtotal = sum(item['price'] * item['quantity'] for item in items)
    if is_vip:
        discount = 0.1  # 10% VIP discount
        subtotal *= (1 - discount)
    tax_rate = 0.08  # 8% tax
    total = subtotal * (1 + tax_rate)
    return round(total, 2)

def format_receipt(items):
    receipt_lines = [f"{item['name']}: {item['quantity']} x ${item['price']:.2f} = ${item['price']*item['quantity']:.2f}" for item in items]
    return "\n".join(receipt_lines)

def process_order(items, is_vip):
    validate_items(items)
    total = calculate_pricing(items, is_vip)
    receipt = format_receipt(items)
    return {'total': total, 'receipt': receipt}
